  private func activePresenter() -> UIViewController? { if let presenter, let scene = presenter.viewIfLoaded?.window?.windowScene, scene.activationState == .foregroundActive { return topPresenter(from: presenter) }; let scenes = UIApplication.shared.connectedScenes.compactMap { $0 as? UIWindowScene }.filter { $0.activationState == .foregroundActive }; for scene in scenes { if let root = scene.windows.first(where: { $0.isKeyWindow })?.rootViewController { return topPresenter(from: root) } }; guard let presenter else { return nil }; return topPresenter(from: presenter) }
