  private func cleanupOrphanedExports(now: Date = Date()) { let root = exportRootDirectory(); guard let sessions = try? FileManager.default.contentsOfDirectory(at: root, includingPropertiesForKeys: [.contentModificationDateKey, .isDirectoryKey], options: [.skipsHiddenFiles]) else { return }; let active = temporaryExportURL?.deletingLastPathComponent().standardizedFileURL; for session in sessions { guard session.standardizedFileURL != active, let values = try? session.resourceValues(forKeys: [.contentModificationDateKey, .isDirectoryKey]), values.isDirectory == true, let modified = values.contentModificationDate, now.timeIntervalSince(modified) >= Self.orphanLifetime else { continue }; try? FileManager.default.removeItem(at: session) } }
